<script setup lang="ts">import{ref}from'vue';import{ChevronDown}from'lucide-vue-next';import type{Content}from'../types';defineProps<{items:Content[]}>();const active=ref<number|null>(null);</script><template><div class="divide-y divide-slate-200 rounded-2xl border border-slate-200"><div v-for="item in items" :key="item.id"><button class="flex w-full items-center justify-between p-5 text-left font-bold" @click="active=active===item.id?null:item.id" :aria-expanded="active===item.id"><span>{{item.title}}</span><ChevronDown :class="{'rotate-180':active===item.id}"/></button><p v-if="active===item.id" class="px-5 pb-5 leading-7 text-slate-600">{{item.content}}</p></div></div></template>
